function Stat({label,value,foot,green=false,icon}:{label:string;value:string;foot:string;green?:boolean;icon?:React.ReactNode}){return <div className={`stat ${green?'green-stat':''}`}><div className="stat-label">{label}{icon&&<span className="stat-icon">{icon}</span>}</div><strong>{value}</strong><span className="stat-foot">{foot}</span></div>}
function ServiceIcon({name,color}:{name:string;color:string}){return <span className="service-icon" style={{background:color+'14',color}}>{name.slice(0,1).toUpperCase()}</span>}
function Empty({title,text,small=false,action}:{title:string;text:string;small?:boolean;action?:()=>void}){return <div className={`empty ${small?'small':''}`}><div className="empty-icon"><Layers size={27}/></div><h3>{title}</h3><p>{text}</p>{action&&<button className="primary" onClick={action}><Plus size={18}/>Añadir servicio</button>}</div>}
function Modal({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const prior=document.activeElement as HTMLElement;const prev=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const els=ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([hidden]), select, textarea, [tabindex="0"]');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',handler);return ()=>{document.body.style.overflow=prev;document.removeEventListener('keydown',handler);prior?.focus()}},[]);return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-label={title} ref={ref} tabIndex={-1}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Cerrar"><X size={21}/></button></div>{children}</div></div>}
function Auth({onDemo}:{onDemo:()=>void}){const [mode,setMode]=useState('login'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');setMessage('');const f=new FormData(e.currentTarget),email=String(f.get('email')).trim(),password=String(f.get('password'));try{if(mode==='register'){const {data,error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin+import.meta.env.BASE_URL}});if(error)throw error;if(!data.session)setMessage('Revisa tu correo para confirmar la cuenta. Después vuelve aquí e inicia sesión.')}else if(mode==='reset'){const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin+import.meta.env.BASE_URL+'?reset=1'});if(error)throw error;setMessage('Revisa tu correo para restablecer la contraseña.')}else{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error}}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <div className="auth-screen"><div className="auth-brand brand"><div className="brand-mark">F<span/></div>Finanzas</div><div className="auth-card"><div className="auth-icon"><Wallet size={31}/></div><h1>Tu dinero, claro.</h1><p>Tus suscripciones, pagos y ahorro.<br/>Todo en tu propio espacio.</p><div className="auth-tabs"><button className={mode==='login'?'active':''} onClick={()=>{setMode('login');setError('');setMessage('')}}>Entrar</button><button className={mode==='register'?'active':''} onClick={()=>{setMode('register');setError('');setMessage('')}}>Crear cuenta</button></div>{mode==='register'&&<p className="signup-note">Usa el mismo correo de tu cuenta de Supabase para recibir la confirmación.</p>}<form onSubmit={submit}><label>Correo electrónico<input required type="email" name="email" autoComplete="email" placeholder="tu@correo.com"/></label>{mode!=='reset'&&<label>Contraseña<input required type="password" name="password" minLength={8} autoComplete={mode==='register'?'new-password':'current-password'} placeholder="Al menos 8 caracteres"/></label>}{error&&<div className="error" role="alert">{error}</div>}{message&&<div className="success" role="status">{message}</div>}<button className="primary" disabled={busy}>{busy?'Un momento…':mode==='register'?'Crear mi cuenta':mode==='reset'?'Enviar enlace':'Entrar a Finanzas'}</button></form><button className="forgot" onClick={()=>setMode('reset')}>Olvidé mi contraseña</button><PasskeyLogin/><div className="auth-divider"><span>o explora primero</span></div><button className="secondary demo-button" onClick={onDemo}>Ver demostración <ChevronRight size={18}/></button><small className="auth-privacy"><ShieldCheck size={15}/>Tus datos solo son visibles en tu cuenta.</small></div></div>}
function Detail({item,year,cutoff,busy,onBack,onEdit,onPayment,onPeriod,onSaving,onNewPayment,onNewRate,onSave,onResume,onConfirm,onDelete}:{item:Item;year:number;cutoff:string;busy:boolean;onBack:()=>void;onEdit:()=>void;onPayment:(p:Charge)=>void;onPeriod:(p:Period)=>void;onSaving:(s:Saving)=>void;onNewPayment:()=>void;onNewRate:()=>void;onSave:()=>void;onResume:()=>void;onConfirm:()=>void;onDelete:()=>void}){const p=currentPeriod(item)??item.periods.at(-1),paid=actualPayments([item],year,cutoff),rows=charges(item,year),pending=rows.filter(p=>p.due<=cutoff&&p.status==='pending');const chart=months.map((m,k)=>({name:m,paid:sum(paid.filter(p=>Number(p.date.slice(5,7))===k+1).map(p=>p.amount)),planned:sum(rows.filter(p=>Number(p.due.slice(5,7))===k+1&&p.status==='pending').map(p=>p.amount))}));return <><button className="back-button" onClick={onBack}><ChevronLeft size={19}/>Volver</button><div className="detail-header"><ServiceIcon name={item.name} color={item.color}/><div><span className="eyebrow">{item.kind==='bill'?'PAGO RECURRENTE':'SUSCRIPCIÓN'}</span><h1>{item.name}</h1><p>{isSaving(item)?'Cancelada · generando ahorro':item.variable?'Importe variable':'Importe fijo'} · {p?.card||'Sin tarjeta'}</p></div><button className="secondary" onClick={onEdit}><Settings2 size={18}/>Editar</button></div><div className="stats-grid"><Stat label={isSaving(item)?'Ahorro mensual':'Costo mensual equivalente'} value={money(isSaving(item)?savingMonthly(item):monthly(item))} foot={p?.cycle==='annual'?`Pago anual de ${money(p.amount)}`:'Según el importe actual'}/><Stat label={`Pagado en ${year}`} value={money(sum(paid.map(p=>p.amount)))} foot={`Hasta ${fullDate(cutoff)}`}/><Stat label={item.savings.length?'Ahorro acumulado':'Pagos confirmados'} value={item.savings.length?money(saved(item,year,cutoff)):String(paid.length)} foot={item.savings.length?`Cargos evitados en ${year}`:`De este año, hasta el período elegido`} green={!!item.savings.length}/></div><section className="panel"><div className="panel-heading"><div><h2>Historial de {year}</h2><p>Pagado y pendiente, mes a mes</p></div></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={chart} margin={{left:-15,right:5,top:12}}><CartesianGrid vertical={false} strokeDasharray="3 5" stroke="#edf0f5"/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false} tickFormatter={v=>'$'+v}/><Tooltip formatter={v=>money(Number(v))}/><Bar dataKey="paid" name="Pagado" fill={item.color} radius={[5,5,0,0]}/><Bar dataKey="planned" name="Pendiente" fill="#dce3ef" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div><div className="legend"><span><i style={{background:item.color}}/>Pagado</span><span><i style={{background:'#dce3ef'}}/>Pendiente</span></div></section><section className="panel history"><div className="panel-heading"><div><h2>Cada pago, en detalle</h2><p>Pulsa un cargo para corregir importe, fecha, tarjeta o estado.</p></div><button className="secondary" disabled={busy} onClick={onNewPayment}><Plus size={18}/>Pago manual</button></div>{pending.length>0&&<div className="confirm-row"><span>{pending.length} cargos vencidos por confirmar</span><button disabled={busy} className="text-button" onClick={onConfirm}>Confirmar pagados</button></div>}{rows.length?rows.map(r=><button key={r.due} className="payment-row" onClick={()=>onPayment(r)}><span className={`payment-status ${r.status}`}>{r.status==='paid'?<Check size={18}/>:r.status==='skipped'?<X size={17}/>:<Clock size={18}/>}</span><span className="payment-description"><b>{fullDate(r.due)}</b><small>{r.status==='paid'?`Pagado ${fullDate(r.date)}`:r.status==='skipped'?'Omitido':r.estimated?'Previsto · sin confirmar':'Pendiente'} · {r.card||'Sin tarjeta'}</small>{r.note&&<small>{r.note}</small>}</span><b>{money(r.amount)}</b><ChevronRight size={17}/></button>):<Empty small title="Sin cargos en este año" text="Puedes registrar un pago manual o ajustar el calendario."/>}</section><section className="panel"><div className="panel-heading"><div><h2>Calendario y tarifas</h2><p>El historial confirmado conserva sus cantidades.</p></div><button className="text-button" disabled={isSaving(item)} onClick={onNewRate}>Cambiar tarifa</button></div>{item.periods.map(p=><button className="period-row" key={p.id} onClick={()=>onPeriod(p)}><div><b>{money(p.amount)} · {p.cycle==='annual'?'anual':'mensual'}</b><small>Desde {fullDate(p.start)}{p.end?` hasta ${fullDate(p.end)} (excluido)`:' · vigente'} · Día {p.day} · {p.card||'Sin tarjeta'}</small></div><Settings2 size={17}/></button>)}</section>{item.savings.length>0&&<section className="panel"><div className="panel-heading"><div><h2>Períodos de ahorro</h2><p>También puedes corregir sus fechas e importes.</p></div></div>{item.savings.map(s=><button className="period-row" key={s.id} onClick={()=>onSaving(s)}><div><b>{money(s.amount)} · {s.cycle==='annual'?'anual':'mensual'}</b><small>Desde {fullDate(s.from)}{s.to?` hasta ${fullDate(s.to)}`:' · en curso'}</small></div><Settings2 size={17}/></button>)}</section>}{item.notes&&<section className="panel notes-panel"><h2>Notas</h2><p>{item.notes}</p></section>}<div className="detail-actions">{item.kind==='subscription'&&(isSaving(item)?<button className="secondary" onClick={onResume}><RefreshCw size={18}/>Reactivar suscripción</button>:<button className="primary green-button" onClick={onSave}><TrendingDown size={19}/>Ahorrar · ya la cancelé</button>)}<button className="danger-button" onClick={onDelete} disabled={busy}><Trash2 size={18}/>Eliminar servicio</button></div><p className="fine-print">«Ahorrar» registra tu cancelación aquí. Cancela el servicio directamente con el proveedor.</p></>}
function Editor({modal,busy,error,year,cutoff,defaultKind,onClose,onSubmit}:{modal:{type:string;item?:Item;payment?:Charge;period?:Period;saving?:Saving};busy:boolean;error:string;year:number;cutoff:string;defaultKind:Item['kind'];onClose:()=>void;onSubmit:(i:Item)=>Promise<void>}){
 const {type,item,payment,saving}=modal;const p=modal.period??item?.periods.at(-1);const [localError,setLocalError]=useState('');const title=type==='item'?(item?'Editar servicio':'Añadir servicio'):type==='payment'?'Editar pago':type==='save'?'Registrar cancelación':type==='resume'?'Reactivar suscripción':type==='newRate'?'Nueva tarifa':type==='savingEdit'?'Editar ahorro':'Editar calendario';
 const amount=payment?.amount??saving?.amount??p?.amount??0;const paymentDue=payment?.due??today();
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setLocalError('');const f=new FormData(e.currentTarget);const str=(k:string)=>String(f.get(k)??'').trim();const n=(k:string)=>Number(f.get(k));try{
 if(type==='item'){const nextPeriod:Period={id:p?.id??uid(),start:str('start'),end:p?.end??null,amount:n('amount'),cycle:str('cycle') as Period['cycle'],day:n('day'),card:str('card')};const next:Item={id:item?.id??uid(),name:str('name'),kind:str('kind') as Item['kind'],color:str('color'),notes:str('notes'),variable:f.has('variable'),periods:item?item.periods.map(x=>x.id===p?.id?nextPeriod:x):[nextPeriod],savings:item?.savings??[],payments:item?.payments??[]};if(!item&&f.has('confirmPast'))next.payments=charges(next,year).filter(c=>c.due<=cutoff).map(c=>({id:uid(),due:c.due,date:c.due,amount:c.amount,card:c.card,status:'paid',note:''}));await onSubmit(next);return}
 if(!item)throw Error('Falta el servicio.');let next:Item=structuredClone(item);
 if(type==='payment'){const rec:Payment={id:payment?.id??uid(),due:str('due'),date:str('date'),amount:n('amount'),card:str('card'),status:str('status') as Payment['status'],note:str('note')};if(rec.status==='paid'&&rec.date>today())throw Error('Un pago confirmado no puede tener una fecha futura.');if(next.payments.some(x=>x.due===rec.due&&x.due!==payment?.due))throw Error('Ya existe un pago en esa fecha. Edita ese pago.');if(payment&&rec.due!==payment.due){next.payments=next.payments.filter(x=>x.due!==payment.due);next.payments.push({id:uid(),due:payment.due,date:payment.due,amount:0,card:payment.card,status:'skipped',note:'Fecha prevista corregida'})}next.payments=next.payments.filter(x=>x.due!==rec.due);next.payments.push(rec)}
 if(type==='period'){if(!p)throw Error('Falta el calendario.');const rec:Period={...p,start:str('start'),end:str('end')||null,amount:n('amount'),cycle:str('cycle') as Period['cycle'],day:n('day'),card:str('card')};next.periods=next.periods.map(x=>x.id===p.id?rec:x)}
 if(type==='newRate'||type==='resume'){if(!p)throw Error('Falta la tarifa anterior.');const start=str('start');if(start>today())throw Error('Selecciona hoy o una fecha anterior para activar la tarifa.');if(type==='newRate'){if(start<=p.start)throw Error('La nueva tarifa debe comenzar después de la anterior. Para corregir el importe original, edita el calendario.');next.periods=next.periods.map(x=>x.id===p.id?{...x,end:start}:x)}else{const s=next.savings.find(s=>!s.to);if(!s||start<=s.from)throw Error('La reactivación debe ser posterior a la cancelación.');next.savings=next.savings.map(x=>x.id===s.id?{...x,to:start}:x)}next.periods.push({id:uid(),start,end:null,amount:n('amount'),cycle:str('cycle') as Period['cycle'],day:n('day'),card:str('card')})}
 if(type==='save'){if(!p||p.end)throw Error('No hay un calendario vigente para cancelar.');const from=str('from');if(from<=p.start||from>today())throw Error('La cancelación debe ser posterior al inicio y no puede estar en el futuro.');if(next.payments.some(x=>x.status==='paid'&&x.due>=from))throw Error('Hay pagos confirmados posteriores a esta cancelación. Corrígelos o selecciona una fecha posterior.');next.periods=next.periods.map(x=>x.id===p.id?{...x,end:from}:x);next.savings.push({id:uid(),from,to:null,amount:n('amount'),cycle:p.cycle,day:p.day,anchor:p.start})}
 if(type==='savingEdit'){if(!saving)throw Error('Falta el período de ahorro.');const from=str('from'),to=str('to')||null;if(from>today()||from<=saving.anchor||(to&&to<=from))throw Error('Revisa el inicio y fin del ahorro.');if(next.payments.some(x=>x.status==='paid'&&x.due>=from&&(!to||x.due<to)))throw Error('Hay pagos confirmados dentro de ese período de ahorro. Corrige los pagos o las fechas.');next.periods=next.periods.map(x=>({...x,end:x.end===saving.from?from:x.end,start:saving.to&&x.start===saving.to&&to?to:x.start}));if(!!to!==!!saving.to)throw Error('Usa «Reactivar suscripción» para cerrar un ahorro en curso.');next.savings=next.savings.map(x=>x.id===saving.id?{...x,from,to,amount:n('amount'),cycle:str('cycle') as Saving['cycle'],day:n('day'),anchor:str('anchor')}:x)}
 const periods=[...next.periods].sort((a,b)=>a.start.localeCompare(b.start));if(periods.some((x,k)=>k>0&&(!periods[k-1].end||periods[k-1].end!>x.start)))throw Error('Los calendarios de tarifas se superponen. Corrige sus fechas.');await onSubmit(next);
 }catch(e){setLocalError((e as Error).message)}}
 const rateFields=<><div className="form-grid"><label>Importe en USD<input name="amount" type="number" required min="0" max="9999999" step="0.01" inputMode="decimal" defaultValue={amount}/></label><label>Frecuencia<select name="cycle" defaultValue={saving?.cycle??p?.cycle??'monthly'}><option value="monthly">Mensual</option><option value="annual">Anual</option></select></label></div><div className="form-grid"><label>Primer cobro / inicio<input name="start" type="date" required defaultValue={type==='newRate'||type==='resume'?today():p?.start??`${new Date().getFullYear()}-01-01`}/></label><label>Día del cobro<input name="day" type="number" required min="1" max="31" step="1" defaultValue={p?.day??new Date().getDate()}/></label></div><label>Nombre de la tarjeta / método<input name="card" maxLength={100} placeholder="Ej. Chase Freedom Unlimited" defaultValue={p?.card??''} list="cards"/></label><p className="field-note">Si el mes no tiene ese día, se usa su último día. Los cobros anuales ocurren en el mes del primer cobro.</p></>;
 return <Modal title={title} onClose={onClose}><form className="editor-form" onSubmit={submit}>{type==='item'&&<><label>Nombre del servicio<input name="name" required maxLength={100} placeholder="Ej. Netflix, Energía…" defaultValue={item?.name??''} autoFocus/></label><div className="form-grid"><label>Sección<select name="kind" defaultValue={item?.kind??defaultKind} disabled={!!item?.savings.length}><option value="subscription">Suscripciones</option><option value="bill">Pagos recurrentes</option></select>{!!item?.savings.length&&<input name="kind" hidden readOnly value={item.kind}/>}</label><label>Color<select name="color" defaultValue={item?.color??COLORS[0]}>{COLORS.map((c,i)=><option key={c} value={c}>{['Azul','Violeta','Rosa','Verde','Ámbar','Celeste'][i]}</option>)}{item&&!COLORS.includes(item.color)&&<option value={item.color}>{item.color}</option>}</select></label></div>{rateFields}<label className="checkbox-label"><input name="variable" type="checkbox" defaultChecked={item?.variable??defaultKind==='bill'}/>El importe puede cambiar cada mes</label><label>Notas<textarea name="notes" maxLength={2000} rows={3} placeholder="Plan, condiciones o cualquier detalle" defaultValue={item?.notes??''}/></label>{!item&&<label className="checkbox-label"><input name="confirmPast" type="checkbox"/>Confirmo que ya pagué los cargos vencidos de {year} hasta {fullDate(cutoff)} con este importe</label>}{item&&<p className="field-note">Esto corrige el último calendario. Para un cambio de precio desde una fecha, usa «Cambiar tarifa». Los pagos confirmados no cambian.</p>}</>}
 {(type==='period'||type==='newRate'||type==='resume')&&<>{rateFields}{type==='period'&&<label>Fin del calendario (excluido)<input name="end" type="date" defaultValue={p?.end??''}/></label>}<p className="field-note">Los importes ya confirmados conservan su valor. Puedes corregirlos individualmente en el historial.</p></>}
 {type==='payment'&&<><div className="form-grid"><label>Fecha prevista<input name="due" type="date" required defaultValue={paymentDue}/></label><label>Fecha real del pago<input name="date" type="date" required defaultValue={payment?.status==='paid'?payment.date:paymentDue>today()?today():paymentDue}/></label></div><div className="form-grid"><label>Importe real en USD<input name="amount" type="number" required min="0" max="9999999" step="0.01" inputMode="decimal" defaultValue={amount}/></label><label>Estado<select name="status" defaultValue={payment?.status==='skipped'?'skipped':'paid'}><option value="paid">Pagado</option><option value="pending">Pendiente</option><option value="skipped">Omitido / no se cobró</option></select></label></div><label>Nombre de la tarjeta / método<input name="card" maxLength={100} defaultValue={payment?.card??p?.card??''}/></label><label>Nota<textarea name="note" rows={3} maxLength={2000} defaultValue={payment?.note??''}/></label><p className="field-note">Solo los pagos marcados «Pagado» cuentan en el total anual, según la fecha real de pago.</p></>}
 {type==='save'&&<><div className="info-box"><TrendingDown size={22}/><p>Se conservarán tus pagos anteriores. El ahorro comienza con los cargos que evites desde la cancelación.</p></div><label>Fecha de cancelación efectiva<input name="from" type="date" required max={today()} defaultValue={today()}/></label><label>Importe que dejarás de pagar ({p?.cycle==='annual'?'anual':'mensual'})<input name="amount" type="number" min="0" max="9999999" step="0.01" inputMode="decimal" required defaultValue={amount}/></label><p className="field-note">Debes haber cancelado el servicio con su proveedor. Esta app solo registra tus finanzas.</p></>}
 {type==='savingEdit'&&<><div className="form-grid"><label>Inicio del ahorro<input name="from" type="date" required defaultValue={saving?.from}/></label><label>Fin del ahorro<input name="to" type="date" defaultValue={saving?.to??''} readOnly={!saving?.to}/></label></div><div className="form-grid"><label>Importe evitado<input name="amount" type="number" min="0" max="9999999" step="0.01" required defaultValue={saving?.amount}/></label><label>Frecuencia<select name="cycle" defaultValue={saving?.cycle}><option value="monthly">Mensual</option><option value="annual">Anual</option></select></label></div><div className="form-grid"><label>Día del cobro evitado<input name="day" type="number" min="1" max="31" required defaultValue={saving?.day}/></label><label>Fecha original del primer cobro<input name="anchor" type="date" required defaultValue={saving?.anchor}/></label></div></>}
 <datalist id="cards"><option value="Chase Sapphire Preferred"/><option value="Chase Freedom Unlimited"/><option value="Discover"/><option value="Cuenta bancaria"/><option value="ATH Móvil"/></datalist>{(localError||error)&&<div className="error" role="alert">{localError||error}</div>}<div className="form-actions"><button className="secondary" type="button" onClick={onClose} disabled={busy}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando…':type==='save'?'Registrar ahorro':'Guardar cambios'}</button></div></form></Modal>
}

function PasswordRecovery({onClose}:{onClose:()=>void}){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <Modal title="Nueva contraseña" onClose={onClose}><form className="editor-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const password=String(f.get('password'));if(password!==String(f.get('confirm'))){setError('Las contraseñas no coinciden.');return}setBusy(true);const {error}=await supabase.auth.updateUser({password});setBusy(false);if(error)setError(error.message);else onClose()}}><label>Nueva contraseña<input name="password" type="password" required minLength={8} autoComplete="new-password"/></label><label>Confirma la contraseña<input name="confirm" type="password" required minLength={8} autoComplete="new-password"/></label>{error&&<div className="error">{error}</div>}<button className="primary" disabled={busy}>{busy?'Guardando…':'Guardar contraseña'}</button></form></Modal>}

function passkeyMessage(error:{code?:string;message:string}){if(error.code==='passkey_disabled')return 'El acceso con clave de acceso no está habilitado. Puedes entrar con tu contraseña.';if(error.code==='webauthn_credential_not_found')return 'Primero entra con tu correo y activa Face ID en Mi cuenta.';if(error.message.toLowerCase().includes('cancel')||error.message.includes('NotAllowedError')||error.code==='ERROR_CEREMONY_ABORTED')return 'Solicitud cancelada. Puedes volver a intentarlo o usar tu contraseña.';return error.message;}
function PasskeyLogin(){const [supported,setSupported]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');useEffect(()=>{setSupported(window.isSecureContext&&typeof PublicKeyCredential!=='undefined')},[]);if(!supported)return null;return <div className="passkey-login"><button className="secondary" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{const {error}=await supabase.auth.signInWithPasskey();if(error)setError(passkeyMessage(error))}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><ScanFace size={21}/>{busy?'Verificando…':'Entrar con Face ID / clave de acceso'}</button><p>Actívalo una vez desde Mi cuenta en tu iPhone.</p>{error&&<div className="error" role="alert">{error}</div>}</div>}
function PasskeySettings(){const [supported,setSupported]=useState(false),[busy,setBusy]=useState(false),[keys,setKeys]=useState<{id:string;friendly_name?:string;created_at:string}[]>([]),[error,setError]=useState(''),[message,setMessage]=useState('');async function list(){const {data,error}=await supabase.auth.passkey.list();if(error)setError(passkeyMessage(error));else setKeys(data??[])}useEffect(()=>{setSupported(window.isSecureContext&&typeof PublicKeyCredential!=='undefined');void list()},[]);return <section className="passkey-settings"><div className="passkey-heading"><ScanFace size={24}/><div><h3>Face ID y claves de acceso</h3><p>En iPhone, guarda tu clave en Contraseñas de iCloud.</p></div></div>{keys.map(k=><div className="passkey-row" key={k.id}><KeyRound size={17}/><span>{k.friendly_name||'Clave de acceso'}<small>Creada {fullDate(k.created_at.slice(0,10))}</small></span><button className="danger-button" disabled={busy} aria-label="Eliminar clave de acceso" onClick={async()=>{if(!confirm('¿Eliminar esta clave de acceso? Podrás seguir entrando con tu contraseña.'))return;setBusy(true);const {error}=await supabase.auth.passkey.delete({passkeyId:k.id});setBusy(false);if(error)setError(passkeyMessage(error));else{setMessage('Clave de acceso eliminada');await list()}}}><Trash2 size={17}/></button></div>)}{error&&<div className="error" role="alert">{error}</div>}{message&&<div className="success" role="status">{message}</div>}<button className="primary" disabled={busy||!supported} onClick={async()=>{setBusy(true);setError('');setMessage('');try{const {error}=await supabase.auth.registerPasskey();if(error)setError(passkeyMessage(error));else{setMessage('Clave de acceso guardada. Ya puedes entrar con Face ID en este iPhone.');await list()}}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><ScanFace size={19}/>{busy?'Configurando…':keys.length?'Añadir otra clave de acceso':'Activar Face ID / clave de acceso'}</button><p className="passkey-explain">{supported?'El dispositivo puede usar Face ID, Touch ID o su código para verificarte. La app no recibe tu rostro.':'Abre la app en Safari o un navegador compatible con claves de acceso.'}</p></section>}
